import "./Task.css";
import { useBrowser } from "../../context/browser-context";
import { Fragment, useEffect } from "react";

export const Task = () => {

  const {time, message, name, browserDispatch} = useBrowser();

  useEffect(()=> {
    getCurrentTime();
    // eslint-disable-next-line
  }, [time, message])

  const getCurrentTime = () => {
    const today = new Date();
    const hours = today.getHours();
    const minutes = today.getMinutes();

    const hour = hours < 10 ? `0${hours}`: hours; 
    const minute = minutes < 10 ? `0${minutes}` : minutes; 

    const currentTime = `${hour}:${minute}`
    //console.log(currentTime, "current time")
    setTimeout(getCurrentTime, 1000);

    browserDispatch({
      type: "TIME",
      payload: currentTime
    })

    browserDispatch({
      type: "MESSAGE",
      payload: hours
    })
  }

  return (
    <div className="task-container d-flex direction-column align-center gap">
        <span className="heading-1">{time}</span>
        <span className="heading-2">{message}, {name}</span>
        <Fragment>
          <span className="heading-3">What is your main focus for today?</span>

        </Fragment>
    </div>

  )
}
